#!/usr/bin/env node
/** Scratch probe for the History/Borders view (not part of the repo). */
import { spawn } from 'node:child_process';
import { mkdtemp, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const base = process.argv[2] || 'http://127.0.0.1:8787';
const outDir = process.argv[3] || '/tmp/hz-shots';
const port = 9441;
const bin = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome'].find(Boolean);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-hz-'));
const child = spawn(bin, ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`,
  '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,1000', 'about:blank'], { stdio: ['ignore', 'ignore', 'ignore'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function endpoint(p) {
  for (let i = 0; i < 60; i++) {
    try { const r = await fetch(`http://127.0.0.1:${port}${p}`); if (r.ok) return r.json(); } catch {}
    await sleep(250);
  }
  throw new Error('CDP not reachable');
}
const t = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(t.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = []; const failed = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(d.params.type)) logs.push(d.params.args.map((a) => a.value ?? a.description).join(' '));
  else if (d.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + (d.params.exceptionDetails.exception?.description || d.params.exceptionDetails.text));
  else if (d.method === 'Network.loadingFailed') failed.push(d.params.errorText + ' ' + d.params.type);
  else if (d.method === 'Log.entryAdded' && d.params.entry.level === 'error') logs.push('LOG ' + d.params.entry.text);
};
const send = (method, params = {}) => new Promise((res) => { const mid = ++id; pending.set(mid, res); ws.send(JSON.stringify({ id: mid, method, params })); });
await send('Page.enable'); await send('Runtime.enable'); await send('Network.enable'); await send('Log.enable');
const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description || 'eval error');
  return r.result?.result?.value;
};
const shot = async (name) => { const r = await send('Page.captureScreenshot', { format: 'png' }); await writeFile(path.join(outDir, name), Buffer.from(r.result.data, 'base64')); };
const waitFor = async (expr, label, timeout = 25000) => {
  const start = Date.now();
  for (;;) {
    const v = await evaluate(expr).catch(() => null);
    if (v) return v;
    if (Date.now() - start > timeout) throw new Error('timeout waiting for ' + label);
    await sleep(300);
  }
};
const geom = `(() => { const c = document.querySelector('#hz-canvas') || document.querySelector('.hz__canvas') || document.querySelector('#history-view canvas'); if (!c) return ''; const ctx = c.getContext('2d'); const d = ctx.getImageData(0,0,c.width,c.height).data; let h = 2166136261; for (let i=0;i<d.length;i+=97) { h ^= d[i]; h = Math.imul(h, 16777619); } return {w:c.width,h:c.height,hash:(h>>>0)}; })()`;

await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: `${base}/?view=history&year=1800` });
await waitFor(`document.querySelector('#hz-status') && /snapshot|Snapshot/.test(document.querySelector('#hz-status').textContent)`, 'status');
await sleep(1200);
console.log('status:', await evaluate(`document.querySelector('#hz-status').textContent.trim()`));
console.log('heading:', await evaluate(`(document.querySelector('#hz-heading')||{}).textContent`));
console.log('canvas:', JSON.stringify(await evaluate(geom)));
console.log('features:', await evaluate(`(() => { const el = document.querySelector('#hz-details'); return document.querySelectorAll('.hz__label, .hz-label').length; })()`));
console.log('url:', await evaluate('location.href'));
await shot('hz-1800.png');
const shape1800 = await evaluate(geom);

for (const year of ['1900', '1000', '-323']) {
  await send('Page.navigate', { url: `${base}/?view=history&year=${year}` });
  await waitFor(`document.querySelector('#hz-status') && /Snapshot/.test(document.querySelector('#hz-status').textContent)`, 'status ' + year);
  await sleep(1500);
  const shape = await evaluate(geom);
  console.log(year, 'status:', await evaluate(`document.querySelector('#hz-status').textContent.trim()`));
  console.log(year, 'geom:', JSON.stringify(shape), 'changed:', shape && shape.hash !== shape1800.hash);
  await shot(`hz-${year.replace('-', 'bc')}.png`);
}

// click a polity: use the select to pick and check the details panel
await send('Page.navigate', { url: `${base}/?view=history&year=1900` });
await waitFor(`document.querySelector('#hz-polity') && document.querySelector('#hz-polity').options.length > 3`, 'polity select');
await sleep(1000);
const polityInfo = await evaluate(`(() => { const s = document.querySelector('#hz-polity'); const o = s.options[1]; return { count: s.options.length, second: o ? o.value || o.textContent : null }; })()`);
console.log('polity options:', JSON.stringify(polityInfo));
if (polityInfo?.second) {
  await evaluate(`(() => { const s = document.querySelector('#hz-polity'); s.selectedIndex = 1; s.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`);
  try {
    const detail = await waitFor(`(() => { const d = document.querySelector('#hz-details'); if (!d || d.hidden) return ''; return { title: d.querySelector('h2,h3')?.textContent || '', text: d.textContent.replace(/\\s+/g,' ').slice(0, 400) }; })()`, 'details panel', 8000);
    console.log('details:', JSON.stringify(detail));
    await shot('hz-details.png');
  } catch (e) { console.log('details: none —', e.message); }
}
console.log('console issues:', JSON.stringify(logs.slice(0, 10)));
console.log('failed requests:', JSON.stringify(failed.slice(0, 10)));
child.kill('SIGKILL');
process.exit(0);

