  const p = (lat, lon) => { const q = m.projectPoint(lat, lon, view, size); return [Math.round(q.x), Math.round(q.y)]; };
  return { size, zoom: Number(zoom.toFixed(3)), worldPx: Math.round(256*2**zoom),
    greenwich: p(0,0), mexico: p(19.4,-99.1), sydney: p(-33.9,151.2), cairo: p(30,31.2), lat60: p(60,0), lat70: p(70,0) };
})()`);
console.log('fit:', JSON.stringify(geo));
console.log('url:', await ev('location.href'));
console.log('status:', await ev(`document.querySelector('#hz-status').textContent.trim()`));
console.log('note:', await ev(`document.querySelector('#hz-note')?.textContent.trim()`));
