  const detail = await ev(`(() => { const d = document.querySelector('#hz-details'); return { hidden: d.hidden, title: d.querySelector('#hz-details-title')?.textContent || '', text: d.textContent.replace(/\\s+/g,' ').slice(0, 220) }; })()`);
